const $=s=>document.querySelector(s);let all=[],selected=null,appMeta={},buildVersion='',identity={pages:[]};
const evidencePage=document.querySelector('.app>main'),sectionPage=$('#infoModal');evidencePage.id='evidencePage';$('#app').appendChild(sectionPage);sectionPage.className='section-page hidden';
const navRoutes={evidenceNav:'evidence',casesNav:'cases',activityNav:'activity',usageNav:'usage',reportsNav:'reports',directoryNav:'directory',auditNav:'audit',settingsNav:'settings'};
function configureAccess(me){identity=me;const allowed=new Set(me.pages||[]);Object.entries(navRoutes).forEach(([id,page])=>$('#'+id).classList.toggle('hidden',!allowed.has(page)));const requested=(location.hash||'').slice(1);if(!allowed.has(requested)){const first=Object.values(navRoutes).find(page=>allowed.has(page));if(first)history.replaceState({},'','#'+first)}}
function applyTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('jo-theme',theme);const button=$('#themeToggle');if(button){button.setAttribute('aria-pressed',theme==='dark');button.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`);button.querySelector('em').textContent=theme==='dark'?'Dark':'Light'}}
function configureTheme(){let button=$('#themeToggle');if(!button){button=document.createElement('button');button.id='themeToggle';button.className='theme-switch';button.innerHTML='<span>Appearance</span><i aria-hidden="true"><b></b></i><em>Light</em>';document.querySelector('.aside-foot').insertBefore(button,$('#logout'))}const saved=localStorage.getItem('jo-theme')||((window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light');applyTheme(saved);button.onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
async function configureAuth(){try{const c=await fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json());buildVersion=c.version||'';let badge=$('#buildVersion');if(!badge){badge=document.createElement('div');badge.id='buildVersion';badge.className='build-version';document.querySelector('.aside-foot').insertBefore(badge,$('#logout'))}badge.textContent=`JO AI Monitor · v${buildVersion||'unknown'}`;$('#entraLogin').classList.toggle('hidden',!c.entra_enabled);$('#loginForm').classList.toggle('hidden',!c.local_enabled);$('#authDivider').classList.toggle('hidden',!(c.entra_enabled&&c.local_enabled))}catch{}const err=new URLSearchParams(location.search).get('auth_error');if(err){$('#loginError').textContent=err==='access_not_assigned'?'Your account is not assigned an authorized JO AI Monitor role or group.':'Microsoft sign-in could not be completed.';history.replaceState({},'',location.pathname)}}
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...opts});if(r.status===401){showLogin();throw Error('Authentication required')}if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(j.detail||'Request failed')}return r.json()}
