$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});const me=await api('/api/auth/me');configureAccess(me);showApp();if((me.pages||[]).includes('evidence'))await load();activateRoute()}catch(x){$('#loginError').textContent=x.message}})
