function openInfo(id,eyebrow,title,status){setActive(id);setRoute(id);closeDetail();evidencePage.classList.add('hidden');sectionPage.classList.remove('hidden');$('#infoEyebrow').textContent=eyebrow;$('#infoTitle').textContent=title;$('#infoStatus').textContent=status;$('#infoBody').innerHTML='<div class="modal-message">Loading…</div>';$('#auditModal').classList.add('hidden');window.scrollTo({top:0,behavior:'auto'})}
function viewError(x){$('#infoBody').innerHTML=`<div class="modal-message">This view could not be loaded: ${esc(x.message)}</div>`}
function number(n){return Number(n||0).toLocaleString()}
function money(n){return Number(n||0).toLocaleString(undefined,{style:'currency',currency:'USD'})}
function barList(rows,key,detail){const max=Math.max(...rows.map(x=>Number(x[key]||0)),1);return `<div class="bar-list">${rows.map(x=>`<div class="bar-row"><div><b>${esc(x.name)}</b><span>${detail(x)}</span></div><div class="bar-track"><i style="width:${Math.max(1,Number(x[key]||0)/max*100)}%"></i></div></div>`).join('')}</div>`}
let usagePeriods=[],pendingUsageFile=null;
function usageReportUrl(period,format){return `/api/reports/usage?period=${encodeURIComponent(period||'')}&format=${format}`}
function renderUsageDashboard(j){const s=j.summary||{},l=j.licensing||{},budget=s.claude_usage_budget?Math.round(s.claude_usage_spend/s.claude_usage_budget*100):0,period=j.period||'';$('#infoStatus').textContent=`${period||'No reporting period'} · ${j.mode==='demo'?'Anonymized demo data':j.mode==='imported'?'Imported analytics':'Live analytics'}`;if(!Object.keys(s).length){$('#infoBody').innerHTML=`<div class="usage-tools"><button id="usageImportEmpty">Import XLSX or CSV</button></div><div class="modal-message">${esc(j.source||'Usage analytics is not configured.')}</div><input id="usageFile" type="file" accept=".xlsx,.csv" hidden>`;$('#usageImportEmpty').onclick=()=>$('#usageFile').click();$('#usageFile').onchange=e=>previewUsageImport(e.target.files[0]);return}const options=usagePeriods.map(x=>`<option value="${esc(x.period)}" ${x.period===period?'selected':''}>${esc(x.period)}${x.source_hash==='demo'?' · demo':' · imported'}</option>`).join('');$('#infoBody').innerHTML=`<div class="usage-tools"><label>Reporting period<select id="usagePeriod">${options||`<option>${esc(period)}</option>`}</select></label><div class="usage-actions"><button id="usageImport">↑ Import</button><a href="${usageReportUrl(period,'pdf')}">PDF</a><a href="${usageReportUrl(period,'csv')}">CSV</a><a href="${usageReportUrl(period,'json')}">JSON</a><a href="${usageReportUrl(period,'html')}" target="_blank">Print</a></div><input id="usageFile" type="file" accept=".xlsx,.csv" hidden></div><div class="usage-kpis"><div class="usage-kpi"><span>Copilot active users</span><b>${number(s.copilot_active_users)}</b><em>${number(s.copilot_interactions)} interactions</em></div><div class="usage-kpi"><span>Claude active users</span><b>${number(s.claude_active_users)}</b><em>${number(s.claude_requests)} API requests</em></div><div class="usage-kpi"><span>Claude usage spend</span><b>${money(s.claude_usage_spend)}</b><em>${budget}% of ${money(s.claude_usage_budget)} limit</em></div><div class="usage-kpi"><span>Estimated monthly run rate</span><b>${money(l.estimated_monthly_run_rate)}</b><em>Seats plus token usage</em></div><div class="usage-kpi"><span>Unassigned Claude seats</span><b>${number(l.claude_seats_unassigned)}</b><em>${number(l.claude_seats_assigned)} of ${number(l.claude_seats_purchased)} assigned</em></div><div class="usage-kpi"><span>Agent-assisted Copilot</span><b>${number(s.agent_interactions)}</b><em>${s.copilot_interactions?Math.round(s.agent_interactions/s.copilot_interactions*100):0}% of interactions</em></div></div><div class="usage-grid"><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">ADOPTION</p><h3>Copilot applications</h3></div><span>Interactions · users</span></div>${barList(j.copilot_apps||[],'interactions',x=>`${number(x.interactions)} · ${number(x.users)} users`)}</section><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">PRODUCT MIX</p><h3>Claude products</h3></div><span>Requests · spend</span></div>${barList(j.claude_products||[],'requests',x=>`${number(x.requests)} · ${money(x.spend)}`)}</section><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">MODEL ECONOMICS</p><h3>Claude model spend</h3></div><span>Spend · requests</span></div>${barList([...(j.claude_models||[])].sort((a,b)=>b.spend-a.spend),'spend',x=>`${money(x.spend)} · ${number(x.requests)} requests`)}</section><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">LICENSING</p><h3>Cost position</h3></div><span>${esc(period)}</span></div><div class="license-list"><div><span>Annual Claude seat contract</span><b>${money(l.claude_annual_seat_cost)}</b></div><div><span>Monthly seat equivalent</span><b>${money(l.monthly_seat_equivalent)}</b></div><div><span>Token usage</span><b>${money(s.claude_usage_spend)}</b></div><div class="total"><span>Estimated monthly run rate</span><b>${money(l.estimated_monthly_run_rate)}</b></div><div><span>Copilot per-use cost</span><b>${esc(l.copilot_usage_cost)}</b></div></div></section></div><section class="usage-panel usage-users"><div class="usage-heading"><div><p class="eyebrow">ROLE-RESTRICTED DETAIL</p><h3>Anonymized utilization sample</h3></div><span>Not for performance management</span></div><table class="info-table"><thead><tr><th>USER</th><th>PROVIDER</th><th>VOLUME</th><th>SURFACES</th><th>ACTIVE DAYS</th><th>SPEND</th></tr></thead><tbody>${(j.top_users||[]).map(x=>`<tr><td>${esc(x.user)}</td><td>${esc(x.provider)}</td><td>${number(x.volume)}</td><td>${number(x.surfaces)}</td><td>${number(x.active_days)}</td><td>${x.spend==null?'Included':money(x.spend)}</td></tr>`).join('')}</tbody></table></section>${usagePeriods.length>1?`<section class="usage-panel usage-history"><div class="usage-heading"><div><p class="eyebrow">HISTORY</p><h3>Reporting periods</h3></div><span>${usagePeriods.length} periods</span></div><table class="info-table"><thead><tr><th>PERIOD</th><th>COPILOT</th><th>CLAUDE</th><th>SPEND</th><th>SOURCE</th></tr></thead><tbody>${usagePeriods.map(x=>`<tr><td><button data-period="${esc(x.period)}">${esc(x.period)}</button></td><td>${number(x.copilot_interactions)}</td><td>${number(x.claude_requests)}</td><td>${money(x.claude_usage_spend)}</td><td>${esc(x.source_name)}</td></tr>`).join('')}</tbody></table></section>`:''}<div class="usage-note"><b>How to read this view</b><ul>${(j.caveats||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><span>Source: ${esc(j.source)}</span>${j.validation?.warnings?.length?`<span class="import-warning">Import warnings: ${esc(j.validation.warnings.join(' · '))}</span>`:''}</div>`;$('#usagePeriod').onchange=e=>openUsage(e.target.value);$('#usageImport').onclick=()=>$('#usageFile').click();$('#usageFile').onchange=e=>previewUsageImport(e.target.files[0]);document.querySelectorAll('[data-period]').forEach(x=>x.onclick=()=>openUsage(x.dataset.period))}
function enhanceUsageUsers(j){const panel=$('.usage-users');if(!panel)return;const detail=(x,i)=>`<tr class="usage-breakdown hidden" data-usage-detail="${i}"><td colspan="7"><div class="usage-breakdown-card"><div><b>${esc(x.user)} usage breakdown</b><span>${esc(x.breakdown_note||'No product-level breakdown was supplied for this reporting period.')}</span></div>${(x.breakdown||[]).length?`<table><thead><tr><th>PRODUCT / APP</th><th>USAGE</th><th>SHARE</th><th>SPEND</th><th>BASIS</th></tr></thead><tbody>${x.breakdown.map(p=>`<tr><td>${esc(p.name)}</td><td>${number(p.volume)} ${x.provider.includes('Copilot')?'interactions':'requests'}</td><td>${x.volume?Math.round(Number(p.volume||0)/x.volume*100):0}%</td><td>${p.spend==null?esc(p.spend_label||'Included'):money(p.spend)}</td><td>${esc(p.basis||'Reported')}</td></tr>`).join('')}</tbody></table>`:'<p>No granular source rows were included in this import.</p>'}</div></td></tr>`;panel.innerHTML=`<div class="usage-heading"><div><p class="eyebrow">ROLE-RESTRICTED DETAIL</p><h3>${j.user_detail_included?'User adoption by product':'Anonymized utilization sample'}</h3></div><span>Click a row for breakdown · ${j.user_detail_included?'named access audited':'identities restricted'}</span></div><table class="info-table usage-user-table"><thead><tr><th></th><th>USER</th><th>PROVIDER</th><th>WHAT THEY USE</th><th>VOLUME</th><th>ACTIVE DAYS</th><th>SPEND</th></tr></thead><tbody>${(j.top_users||[]).map((x,i)=>`<tr class="usage-user-row" data-usage-user="${i}" tabindex="0" aria-expanded="false"><td><button class="usage-expand" aria-label="Show usage breakdown">›</button></td><td>${esc(x.user)}</td><td>${esc(x.provider)}</td><td><div class="product-tags">${(x.products||[]).map(p=>`<span>${esc(p)}</span>`).join('')||`${number(x.surfaces)} surfaces`}</div></td><td>${number(x.volume)}</td><td>${number(x.active_days)}</td><td>${x.spend==null?'Included':money(x.spend)}</td></tr>${detail(x,i)}`).join('')}</tbody></table>`;panel.querySelectorAll('[data-usage-user]').forEach(row=>{const toggle=()=>{const open=row.getAttribute('aria-expanded')==='true';row.setAttribute('aria-expanded',String(!open));row.querySelector('.usage-expand').textContent=open?'›':'⌄';panel.querySelector(`[data-usage-detail="${row.dataset.usageUser}"]`).classList.toggle('hidden',open)};row.onclick=toggle;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}}})}
function correctUsageShares(j){(j.top_users||[]).forEach((x,i)=>{const rows=document.querySelectorAll(`[data-usage-detail="${i}"] tbody tr`),total=(x.breakdown||[]).reduce((sum,p)=>sum+Number(p.volume||0),0);rows.forEach((row,k)=>{if(row.children[2])row.children[2].textContent=total?`${Math.round(Number(x.breakdown[k]?.volume||0)/total*100)}%`:'—'})})}
async function openUsage(period=''){openInfo('usageNav','AI ADOPTION & ECONOMICS','Usage & spend','Loading monthly analytics…');try{const periods=await api('/api/usage/periods');usagePeriods=periods.data||[];const j=await api('/api/usage'+(period?`?period=${encodeURIComponent(period)}`:''));renderUsageDashboard(j);enhanceUsageUsers(j);correctUsageShares(j)}catch(x){viewError(x)}}
async function previewUsageImport(file){if(!file)return;pendingUsageFile=file;$('#infoStatus').textContent='Validating import…';$('#infoBody').innerHTML='<div class="modal-message">Reading and validating the usage workbook…</div>';const form=new FormData();form.append('file',file);try{const r=await fetch('/api/usage/import/preview',{method:'POST',body:form});const j=await r.json();if(!r.ok)throw Error(j.detail||'Import preview failed');const d=j.data,s=d.summary||{},warnings=d.validation?.warnings||[],exists=usagePeriods.some(x=>x.period===d.period);$('#infoStatus').textContent=`Import preview · ${d.period}`;$('#infoBody').innerHTML=`<div class="import-preview"><span class="status-pill ${warnings.length?'off':'on'}">${warnings.length?`${warnings.length} warning${warnings.length===1?'':'s'}`:'Validated'}</span><h3>${esc(file.name)}</h3><p>Reporting period: <b>${esc(d.period)}</b></p><div class="usage-kpis"><div class="usage-kpi"><span>Copilot interactions</span><b>${number(s.copilot_interactions)}</b></div><div class="usage-kpi"><span>Claude requests</span><b>${number(s.claude_requests)}</b></div><div class="usage-kpi"><span>Claude spend</span><b>${money(s.claude_usage_spend)}</b></div></div>${warnings.length?`<div class="import-warnings">${warnings.map(x=>`<p>⚠ ${esc(x)}</p>`).join('')}</div>`:'<p class="import-ok">✓ Source totals reconciled successfully.</p>'}${exists?'<label class="replace-check"><input id="usageReplace" type="checkbox"> Replace the existing reporting period</label>':''}<div class="import-actions"><button id="importCancel">Cancel</button><button id="importConfirm" ${exists?'disabled':''}>Import reporting period</button></div></div>`;if(exists)$('#usageReplace').onchange=e=>$('#importConfirm').disabled=!e.target.checked;$('#importCancel').onclick=()=>openUsage();$('#importConfirm').onclick=()=>confirmUsageImport(d.period,exists&&$('#usageReplace')?.checked)}catch(x){viewError(x)}}
async function confirmUsageImport(period,replace=false){if(!pendingUsageFile)return;$('#infoStatus').textContent='Importing reporting period…';const form=new FormData();form.append('file',pendingUsageFile);try{const r=await fetch(`/api/usage/import?replace=${replace}`,{method:'POST',body:form});const j=await r.json();if(r.status===401){showLogin();throw Error('Authentication required')}if(!r.ok)throw Error(j.detail||'Import failed');pendingUsageFile=null;await openUsage(period)}catch(x){viewError(x)}}
function caseStatusLabel(x){return x.replaceAll('_',' ')}
async function updateInvestigation(id,changes){try{await api('/api/investigations/'+id,{method:'PATCH',body:JSON.stringify(changes)});await openCase(id)}catch(x){$('#caseMessage').textContent=x.message}}
async function addCaseNote(id){const text=$('#caseNote').value;if(!text.trim())return;try{await api(`/api/investigations/${id}/notes`,{method:'POST',body:JSON.stringify({text})});await openCase(id)}catch(x){$('#caseMessage').textContent=x.message}}
async function openCase(id){openInfo('casesNav','INVESTIGATION WORKFLOW',`Case #${id}`,'Loading preserved evidence and timeline…');try{const [c,related]=await Promise.all([api('/api/investigations/'+id),api(`/api/investigations/${id}/related`)]);$('#infoTitle').textContent=c.title;$('#infoStatus').textContent=`Case #${c.id} · updated ${new Date(c.updated_at).toLocaleString()}`;$('#infoBody').innerHTML=`<div class="case-command"><label>Status<select id="caseStatus">${['new','investigating','confirmed','benign','accepted_risk','closed'].map(x=>`<option value="${x}" ${c.status===x?'selected':''}>${caseStatusLabel(x)}</option>`).join('')}</select></label><label>Priority<select id="casePriority">${['critical','high','medium','low'].map(x=>`<option ${c.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Assignee<input id="caseAssignee" value="${esc(c.assignee)}" placeholder="analyst@example.com"></label><label>Due date<input id="caseDue" type="date" value="${esc((c.due_at||'').slice(0,10))}"></label><button id="caseSave">Save changes</button><div class="usage-actions"><a href="/api/investigations/${c.id}/export?format=pdf">PDF package</a><a href="/api/investigations/${c.id}/export?format=json">JSON package</a></div></div><div id="caseMessage"></div><div class="case-overview"><section class="usage-panel"><p class="eyebrow">INVESTIGATION SUMMARY</p><h3>${esc(c.title)}</h3><p>${esc(c.description||'No description has been added.')}</p><div class="case-tags">${c.tags.map(x=>`<span class="surface">${esc(x)}</span>`).join('')}</div><label>Disposition / closure reason<textarea id="caseDisposition" placeholder="Required for benign, accepted risk, or closed cases">${esc(c.disposition)}</textarea></label></section><section class="usage-panel"><p class="eyebrow">ANALYST NOTE</p><textarea id="caseNote" placeholder="Add analysis, decisions, or follow-up context…"></textarea><button id="caseAddNote">Add to timeline</button><p class="case-guidance">Original evidence and analyst commentary remain visibly separate in exports.</p></section></div><section class="usage-panel case-findings"><div class="usage-heading"><div><p class="eyebrow">PRESERVED EVIDENCE</p><h3>${number(c.findings.length)} linked findings</h3></div><span>Immutable snapshots</span></div><table class="info-table"><thead><tr><th>RISK</th><th>FINDING</th><th>USER</th><th>SURFACE</th><th>SNAPSHOT</th></tr></thead><tbody>${c.findings.map(x=>`<tr><td><span class="risk ${esc(x.risk)}">${esc(x.risk)} ${number(x.risk_score)}</span></td><td>${esc(x.title)}<span class="sub">${esc(x.id)}</span></td><td>${esc(x.user?.email||'Unknown')}</td><td>${esc(x.surface)}</td><td>${new Date(x.snapshot.linked_at).toLocaleString()}</td></tr>`).join('')}</tbody></table></section><section class="usage-panel related-findings"><div class="usage-heading"><div><p class="eyebrow">CORRELATION</p><h3>Related findings</h3></div><span>Identity · indicator · provider</span></div>${related.data.slice(0,8).map(x=>`<div class="related-row"><div><b>${esc(x.title)}</b><span>${esc(x.relation_reasons.join(' · '))}</span></div><span class="risk ${esc(x.risk)}">${esc(x.risk)} ${number(x.risk_score)}</span><button data-link="${esc(x.id)}">Link</button></div>`).join('')||'<p class="case-guidance">No additional related findings were detected.</p>'}</section><section class="usage-panel case-timeline"><div class="usage-heading"><div><p class="eyebrow">AUDITABLE HISTORY</p><h3>Case timeline</h3></div><span>${number(c.timeline.length)} events</span></div>${c.timeline.map(x=>`<div class="timeline-event"><i></i><div><b>${esc(caseStatusLabel(x.event_type))}</b><span>${new Date(x.created_at).toLocaleString()} · ${esc(x.actor)}</span><p>${x.event_type==='analyst_note'?esc(x.new_value?.text):esc(x.reason||JSON.stringify(x.new_value||{}))}</p></div></div>`).join('')}</section>`;$('#caseSave').onclick=()=>updateInvestigation(c.id,{status:$('#caseStatus').value,priority:$('#casePriority').value,assignee:$('#caseAssignee').value,due_at:$('#caseDue').value||null,disposition:$('#caseDisposition').value,reason:'Analyst updated case workflow'});$('#caseAddNote').onclick=()=>addCaseNote(c.id);document.querySelectorAll('[data-link]').forEach(x=>x.onclick=async()=>{await api(`/api/investigations/${c.id}/findings/${encodeURIComponent(x.dataset.link)}`,{method:'POST'});openCase(c.id)})}catch(x){viewError(x)}}
async function createInvestigation(){const finding=$('#newCaseFinding').value.trim();try{const c=await api('/api/investigations',{method:'POST',body:JSON.stringify({title:$('#newCaseTitle').value,description:$('#newCaseDescription').value,priority:$('#newCasePriority').value,assignee:$('#newCaseAssignee').value,finding_id:finding,tags:['manual-review']})});await openCase(c.id)}catch(x){$('#newCaseMessage').textContent=x.message}}
