async function loadFindingReport(){const p=new URLSearchParams({date_from:$('#reportFrom')?.value||'',date_to:$('#reportTo')?.value||'',risk:$('#reportRisk')?.value||'all',surface:$('#reportSurface')?.value||'all',include_named_users:$('#reportNamed')?.checked?'true':'false'});$('#reportResults').innerHTML='<div class="modal-message">Calculating report…</div>';try{const j=await api('/api/reports/findings/summary?'+p),r=j.report,s=r.severity;$('#infoStatus').textContent=`${number(r.total)} findings · generated ${new Date(j.generated_at).toLocaleString()}`;$('#reportResults').innerHTML=`<div class="usage-kpis report-kpis"><div class="usage-kpi"><span>Findings</span><b>${number(r.total)}</b><em>Selected range</em></div><div class="usage-kpi"><span>Critical</span><b>${number(s.critical)}</b><em>Immediate review</em></div><div class="usage-kpi"><span>High</span><b>${number(s.high)}</b><em>Priority review</em></div><div class="usage-kpi"><span>Medium</span><b>${number(s.medium)}</b><em>Policy threshold</em></div></div><div class="usage-grid"><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">DETECTION</p><h3>Matched categories</h3></div></div>${barList(Object.entries(r.categories).map(([name,count])=>({name:name.replaceAll('_',' '),count})),'count',x=>number(x.count))}</section><section class="usage-panel"><div class="usage-heading"><div><p class="eyebrow">COVERAGE</p><h3>Findings by surface</h3></div></div>${barList(Object.entries(r.surfaces).map(([name,count])=>({name,count})),'count',x=>number(x.count))}</section></div><section class="usage-panel report-table"><div class="usage-heading"><div><p class="eyebrow">PROVENANCE</p><h3>Compliance findings</h3></div><span>${j.named_users_included?'Named users included':'Identities restricted'}</span></div><table class="info-table"><thead><tr><th>DATE</th><th>RISK</th><th>FINDING</th><th>SURFACE</th><th>IDENTITY</th><th>RULE</th></tr></thead><tbody>${r.findings.slice(0,100).map(x=>`<tr><td>${esc(String(x.created_at).slice(0,10))}</td><td><span class="risk ${esc(x.severity)}">${esc(x.severity)} ${number(x.score)}</span></td><td>${esc(x.title)}<span class="sub">${esc(x.id)}</span></td><td>${esc(x.surface)}</td><td>${esc(x.identity)}</td><td>${esc(x.rule_version)}</td></tr>`).join('')}</tbody></table></section>`}catch(x){$('#reportResults').innerHTML=`<div class="modal-message">${esc(x.message)}</div>`}}
async function createReportSchedule(){const recipients=$('#scheduleRecipients').value.split(',').map(x=>x.trim()).filter(Boolean);try{await api('/api/report-schedules',{method:'POST',body:JSON.stringify({name:$('#scheduleName').value,recipients,frequency:$('#scheduleFrequency').value,format:$('#scheduleFormat').value,include_named_users:$('#reportNamed').checked})});await openReports()}catch(x){$('#scheduleState').textContent=x.message}}
async function openReports(){openInfo('reportsNav','COMPLIANCE & LEADERSHIP','Reports','Loading reporting workspace…');try{const [trends,schedules]=await Promise.all([api('/api/reports/trends'),api('/api/report-schedules')]);const today=new Date().toISOString().slice(0,10),start=new Date(Date.now()-120*86400000).toISOString().slice(0,10);$('#infoBody').innerHTML=`<div class="report-filter"><label>From<input id="reportFrom" type="date" value="${start}"></label><label>To<input id="reportTo" type="date" value="${today}"></label><label>Severity<select id="reportRisk"><option value="all">All severities</option><option>critical</option><option>high</option><option>medium</option></select></label><label>Surface<select id="reportSurface"><option value="all">All surfaces</option>${[...new Set(all.map(x=>x.surface))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="report-check"><input id="reportNamed" type="checkbox" ${schedules.named_user_authorized?'':'disabled'}> Include named users</label><button id="reportApply">Apply</button><div class="usage-actions"><a id="reportPdf">PDF</a><a id="reportCsv">CSV</a><a id="reportJson">JSON</a></div></div><div id="reportResults"></div><section class="usage-panel report-trends"><div class="usage-heading"><div><p class="eyebrow">MONTH-OVER-MONTH</p><h3>Finding trends</h3></div><span>Score and severity history</span></div>${trendBars(trends.risk)}</section><section class="usage-panel schedule-panel"><div class="usage-heading"><div><p class="eyebrow">AUTOMATION</p><h3>Scheduled compliance reports</h3></div><span class="status-pill ${schedules.smtp_configured?'on':'off'}">${schedules.smtp_configured?'Email ready':'SMTP not configured'}</span></div><div class="schedule-form"><input id="scheduleName" placeholder="Monthly compliance review" value="Monthly compliance review"><input id="scheduleRecipients" placeholder="security@example.com, compliance@example.com"><select id="scheduleFrequency"><option>monthly</option><option>weekly</option><option>daily</option></select><select id="scheduleFormat"><option>pdf</option><option>csv</option><option>json</option></select><button id="scheduleCreate">Create schedule</button></div><div id="scheduleState"></div><table class="info-table"><thead><tr><th>NAME</th><th>FREQUENCY</th><th>RECIPIENTS</th><th>NEXT RUN</th><th>LAST STATUS</th><th></th></tr></thead><tbody>${schedules.data.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.frequency)} · ${esc(x.report_format.toUpperCase())}</td><td>${esc(x.recipients.join(', '))}</td><td>${new Date(x.next_run_at).toLocaleString()}</td><td>${esc(x.last_status||'Not run')}</td><td><button class="schedule-delete" data-id="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></section>`;const updateLinks=()=>{['Pdf','Csv','Json'].forEach(x=>$('#report'+x).href=findingReportUrl(x.toLowerCase()))};$('#reportApply').onclick=()=>{updateLinks();loadFindingReport()};['reportFrom','reportTo','reportRisk','reportSurface','reportNamed'].forEach(id=>$('#'+id).onchange=updateLinks);updateLinks();$('#scheduleCreate').onclick=createReportSchedule;document.querySelectorAll('.schedule-delete').forEach(x=>x.onclick=async()=>{await api('/api/report-schedules/'+x.dataset.id,{method:'DELETE'});openReports()});await loadFindingReport()}catch(x){viewError(x)}}
