function openPolicyEditor(p){const editor=$('#policyEditor'),editable=p.status==='draft';editor.innerHTML=`<div class="policy-editor"><div class="usage-heading"><div><p class="eyebrow">${editable?'DRAFT EDITOR':'READ-ONLY POLICY'}</p><h3>${esc(p.version)} · ${esc(p.name)}</h3></div><span>${esc(p.status)}</span></div><label>Name<input id="policyEditName" value="${esc(p.name)}" ${editable?'':'disabled'}></label><label>Description<textarea id="policyEditDescription" ${editable?'':'disabled'}>${esc(p.description)}</textarea></label><div class="policy-numbers"><label>Finding threshold<input id="policyThreshold" type="number" min="0" max="100" value="${p.finding_threshold}" ${editable?'':'disabled'}></label>${Object.entries(p.severity_bands).map(([k,v])=>`<label>${esc(k)}<input data-severity="${esc(k)}" type="number" min="0" max="100" value="${v}" ${editable?'':'disabled'}></label>`).join('')}</div><label>Rules JSON<textarea id="policyRules" class="policy-json" spellcheck="false" ${editable?'':'disabled'}>${esc(JSON.stringify(p.rules,null,2))}</textarea></label>${editable?`<label>Required change / approval reason<input id="policyReason" placeholder="Explain what changed and why"></label><div class="policy-actions"><button id="policySave">Save draft</button><button id="policyApprove">Approve policy</button></div>`:''}</div>`;if(editable){$('#policySave').onclick=async()=>{try{await api(`/api/policies/${p.id}`,{method:'PATCH',body:JSON.stringify(policyEditorPayload())});refreshPolicySettings()}catch(x){alert(x.message)}};$('#policyApprove').onclick=async()=>{const reason=$('#policyReason').value;if(!reason)return;try{await api(`/api/policies/${p.id}/approve`,{method:'POST',body:JSON.stringify({reason})});refreshPolicySettings()}catch(x){alert(x.message)}}}}
function policyEditorPayload(){const bands={};document.querySelectorAll('[data-severity]').forEach(x=>bands[x.dataset.severity]=Number(x.value));return {name:$('#policyEditName').value,description:$('#policyEditDescription').value,finding_threshold:Number($('#policyThreshold').value),severity_bands:bands,rules:JSON.parse($('#policyRules').value),reason:$('#policyReason').value}}
function refreshPolicySettings(){const old=$('.policy-admin');if(old)old.remove();$('#infoBody').dataset.policyLoading='';enhancePolicySettings()}
function schedulePolicySettings(){const body=$('#infoBody');if(body&&$('#settingsNav').classList.contains('active')&&!body.dataset.policyLoading&&body.querySelector('.info-grid'))enhancePolicySettings()}
function closeToEvidence(){closeViews();showEvidence()}
$('#auditClose').onclick=closeToEvidence;$('#infoClose').onclick=closeToEvidence;
$('#auditModal').addEventListener('click',e=>{if(e.target===$('#auditModal'))closeToEvidence()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#detail').classList.contains('open'))closeDetail()});
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function ago(s){const d=(Date.now()-new Date(s))/1000;if(d<3600)return Math.floor(d/60)+'m ago';if(d<86400)return Math.floor(d/3600)+'h ago';return Math.floor(d/86400)+'d ago'}
async function load(){const p=new URLSearchParams({q:$('#search').value,risk:$('#risk').value,surface:$('#surface').value});const j=await api('/api/cases?'+p);appMeta=j;all=j.data;$('#modeLabel').textContent=(j.mode==='demo'?'Demo environment':'Live Compliance API')+(buildVersion?` · v${buildVersion}`:'');$('#suppressedCount').textContent=`${j.suppressed_count||0} below threshold · minimum ${j.finding_threshold||40}`;render()}
function render(){$('#totalCount').textContent=all.length;$('#openCount').textContent=all.filter(x=>['open','review','new'].includes(x.status)).length;$('#criticalCount').textContent=all.filter(x=>x.risk==='critical').length;$('#coverageCount').textContent=new Set(all.map(x=>x.surface)).size;$('#empty').classList.toggle('hidden',all.length>0);$('#rows').innerHTML=all.map(x=>`<tr data-id="${esc(x.id)}" class="${selected===x.id?'selected':''}"><td><span class="risk ${x.risk}">${x.risk} ${x.risk_score??''}</span></td><td><span class="title">${esc(x.title)}</span><span class="sub">${esc(x.id)}</span></td><td>${esc(x.user?.email||'Unknown')}<span class="sub">${esc(x.user?.id||'')}</span></td><td><span class="surface">${esc(x.surface)}</span></td><td>${ago(x.created_at)}<span class="sub">${new Date(x.created_at).toLocaleString()}</span></td><td>›</td></tr>`).join('');document.querySelectorAll('#rows tr').forEach(r=>r.onclick=()=>detail(r.dataset.id))}
async function detail(id){selected=id;render();const pane=$('#detail');pane.classList.add('open');pane.scrollTop=0;drawerBackdrop().classList.add('open');pane.innerHTML='<div class="modal-message">Loading evidence…</div>';try{const x=await api('/api/cases/'+encodeURIComponent(id));const base=all.find(y=>y.id===id)||x;let msgs=x.messages||x.chat_messages||x.data||[];const contexts=(x.contexts||[]).map(c=>`<div class="message"><b>ACCESSED RESOURCE · ${esc(c.contextType||'resource')}</b>${esc(c.displayName||c.contextReference||'Referenced resource')}</div>`).join('');pane.innerHTML=`<button class="detail-close" aria-label="Close evidence detail">×</button><div class="detail-head"><span class="risk ${base.risk}">${esc(base.risk)}</span><h2>${esc(base.title)}</h2><p>${esc(base.summary)}</p>${(base.matched||[]).map(m=>`<span class="surface">${esc(m)}</span>`).join(' ')}</div><div class="meta"><div><span>User</span><b>${esc(base.user?.email)}</b></div><div><span>Surface</span><b>${esc(base.surface)}</b></div><div><span>Created</span><b>${new Date(base.created_at).toLocaleString()}</b></div><div><span>Evidence ID</span><b>${esc(base.id)}</b></div></div><div class="transcript"><h3>VERBATIM EVIDENCE</h3>${msgs.map(m=>`<div class="message ${(m.role||m.sender)==='human'?'human':''}"><b>${esc(m.role||m.sender||m.type||'message')} · ${m.created_at?new Date(m.created_at).toLocaleString():''}</b>${esc(m.text||m.content||JSON.stringify(m))}</div>`).join('')||'<p>No transcript content returned for this record.</p>'}${contexts?'<h3>ACCESSED RESOURCES</h3>'+contexts:''}<div class="actions"><a href="/api/export/${encodeURIComponent(id)}">Download evidence JSON</a></div></div>`;pane.querySelector('.detail-close').onclick=closeDetail}catch(x){pane.innerHTML=`<button class="detail-close" aria-label="Close evidence detail">×</button><div class="modal-message">${esc(x.message)}</div>`;pane.querySelector('.detail-close').onclick=closeDetail}}
let timer;['search','risk','surface'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{clearTimeout(timer);timer=setTimeout(load,250)}));
async function enhanceCaseDetail(){const root=$('.case-timeline');if(!root||root.dataset.enhanced)return;root.dataset.enhanced='1';const match=$('#infoStatus').textContent.match(/Case #(\d+)/);if(!match)return;const id=match[1];try{const c=await api('/api/investigations/'+id);const panel=document.createElement('section');panel.className='usage-panel v081-tools';panel.innerHTML=`<div class="usage-heading"><div><p class="eyebrow">GOVERNANCE CONTROLS</p><h3>Classification and preservation</h3></div><span class="status-pill ${c.legal_hold?'off':'on'}">${c.legal_hold?'Legal hold active':'Standard retention'}</span></div><div class="case-governance"><label>Category<input id="caseCategory" value="${esc(c.category||'security_review')}"></label><label>Escalation<select id="caseEscalation">${['none','watch','management','incident_response','legal'].map(x=>`<option value="${x}" ${c.escalation===x?'selected':''}>${caseStatusLabel(x)}</option>`).join('')}</select></label><button id="caseGovernanceSave">Save classification</button><label>Hold reason<input id="caseHoldReason" value="${esc(c.legal_hold_reason||'')}"></label><button id="caseHold">${c.legal_hold?'Release legal hold':'Place legal hold'}</button></div><div id="governanceMessage"></div><div class="case-collaboration"><div><p class="eyebrow">THREADED COMMENTS</p><div class="comments-list">${(c.comments||[]).map(x=>`<div class="case-comment ${x.parent_id?'reply':''}"><b>${esc(x.actor)}</b><span>${new Date(x.created_at).toLocaleString()}</span><p>${esc(x.body)}</p><button data-reply="${x.id}">Reply</button></div>`).join('')||'<p class="case-guidance">No comments yet.</p>'}</div><textarea id="caseComment" placeholder="Add a comment…"></textarea><input id="commentParent" type="hidden"><button id="caseCommentAdd">Post comment</button></div><div><p class="eyebrow">ATTACHMENTS</p><div class="attachment-list">${(c.attachments||[]).map(x=>`<a href="/api/investigations/${id}/attachments/${x.id}">${esc(x.filename)}<span>${number(x.size)} bytes · SHA-256 ${esc(x.sha256.slice(0,12))}…</span></a>`).join('')||'<p class="case-guidance">No attachments.</p>'}</div><input id="caseAttachment" type="file" accept=".pdf,.txt,.csv,.json,.png,.jpg,.jpeg"><button id="caseUpload">Upload attachment</button><p class="case-guidance">Allowed: PDF, text, CSV, JSON, PNG, JPEG. Files are hashed and stored on the persistent volume.</p></div></div>`;root.parentNode.insertBefore(panel,root);$('#caseGovernanceSave').onclick=async()=>{try{await api('/api/investigations/'+id,{method:'PATCH',body:JSON.stringify({category:$('#caseCategory').value,escalation:$('#caseEscalation').value,reason:'Classification updated'})});openCase(id)}catch(x){$('#governanceMessage').textContent=x.message}};$('#caseHold').onclick=async()=>{try{await api(`/api/investigations/${id}/legal-hold`,{method:'POST',body:JSON.stringify({enabled:!c.legal_hold,reason:$('#caseHoldReason').value})});openCase(id)}catch(x){$('#governanceMessage').textContent=x.message}};document.querySelectorAll('[data-reply]').forEach(x=>x.onclick=()=>{$('#commentParent').value=x.dataset.reply;$('#caseComment').placeholder=`Reply to comment #${x.dataset.reply}`;$('#caseComment').focus()});$('#caseCommentAdd').onclick=async()=>{try{await api(`/api/investigations/${id}/comments`,{method:'POST',body:JSON.stringify({body:$('#caseComment').value,parent_id:Number($('#commentParent').value)||null})});openCase(id)}catch(x){$('#governanceMessage').textContent=x.message}};$('#caseUpload').onclick=async()=>{const file=$('#caseAttachment').files[0];if(!file)return;const form=new FormData();form.append('file',file);const response=await fetch(`/api/investigations/${id}/attachments`,{method:'POST',body:form});const data=await response.json().catch(()=>({}));if(!response.ok){$('#governanceMessage').textContent=data.detail||'Upload failed';return}openCase(id)}}catch(x){root.dataset.enhanced='';}}
async function renderQueueRows(filters){const p=new URLSearchParams(filters),j=await api('/api/investigations?'+p);const body=$('.cases-table tbody');body.innerHTML=j.data.map(x=>`<tr data-case="${x.id}"><td><input type="checkbox" data-select-case="${x.id}"></td><td><b>#${x.id} · ${esc(x.title)}</b><span class="sub">${esc(x.description)}</span></td><td><span class="risk ${esc(x.priority)}">${esc(x.priority)}</span></td><td><span class="surface">${esc(caseStatusLabel(x.status))}</span></td><td>${esc(x.assignee||'Unassigned')}</td><td>${number(x.finding_count)}</td><td>${new Date(x.updated_at).toLocaleString()}</td></tr>`).join('');body.querySelectorAll('tr').forEach(x=>x.onclick=e=>{if(!e.target.matches('input'))openCase(x.dataset.case)})}
async function enhanceCaseQueue(){const table=$('.cases-table');if(!table||table.dataset.enhanced)return;table.dataset.enhanced='1';const head=table.querySelector('thead tr');head.insertAdjacentHTML('afterbegin','<th>SELECT</th>');table.querySelectorAll('tbody tr').forEach(row=>{row.insertAdjacentHTML('afterbegin',`<td><input type="checkbox" data-select-case="${row.dataset.case}"></td>`);row.onclick=e=>{if(!e.target.matches('input'))openCase(row.dataset.case)}});const tools=document.createElement('section');tools.className='usage-panel queue-tools';tools.innerHTML=`<div class="usage-heading"><div><p class="eyebrow">BULK WORKFLOW</p><h3>Selected-case action</h3></div><span>Every change requires a reason</span></div><div class="bulk-form"><select id="bulkField"><option value="assignee">Assign to</option><option value="status">Status</option><option value="priority">Priority</option><option value="escalation">Escalation</option></select><input id="bulkValue" placeholder="New value"><input id="bulkReason" placeholder="Required change reason"><button id="bulkApply">Apply to selected</button></div><div id="bulkMessage"></div><div class="usage-heading queue-heading"><div><p class="eyebrow">SAVED QUEUES</p><h3>Reviewer views</h3></div></div><div class="queue-form"><input id="queueName" placeholder="My critical cases"><select id="queueStatus"><option value="all">All statuses</option><option>new</option><option>investigating</option><option>confirmed</option><option>closed</option></select><select id="queuePriority"><option value="all">All priorities</option><option>critical</option><option>high</option><option>medium</option><option>low</option></select><button id="queueSave">Save queue</button></div><div id="savedQueues"></div>`;table.parentNode.insertBefore(tools,table);$('#bulkApply').onclick=async()=>{const ids=[...document.querySelectorAll('[data-select-case]:checked')].map(x=>Number(x.dataset.selectCase));try{await api('/api/investigation-actions/bulk',{method:'POST',body:JSON.stringify({case_ids:ids,changes:{[$('#bulkField').value]:$('#bulkValue').value},reason:$('#bulkReason').value})});openCases()}catch(x){$('#bulkMessage').textContent=x.message}};async function refreshQueues(){const j=await api('/api/investigation-queues');$('#savedQueues').innerHTML=j.data.map(x=>`<button data-queue='${esc(JSON.stringify(x.filters))}'>${esc(x.name)}</button>`).join('')||'<span class="case-guidance">No saved queues.</span>';document.querySelectorAll('[data-queue]').forEach(x=>x.onclick=()=>renderQueueRows(JSON.parse(x.dataset.queue)))}$('#queueSave').onclick=async()=>{try{await api('/api/investigation-queues',{method:'POST',body:JSON.stringify({name:$('#queueName').value,filters:{status:$('#queueStatus').value,priority:$('#queuePriority').value}})});refreshQueues()}catch(x){$('#bulkMessage').textContent=x.message}};refreshQueues()}
function enhanceBulkExport(){const form=$('.bulk-form');if(!form||$('#bulkExport'))return;const button=document.createElement('button');button.id='bulkExport';button.textContent='Export selected';button.onclick=async()=>{const ids=[...document.querySelectorAll('[data-select-case]:checked')].map(x=>Number(x.dataset.selectCase));if(!ids.length){$('#bulkMessage').textContent='Select at least one case';return}const response=await fetch('/api/investigation-actions/bulk-export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({case_ids:ids})});if(!response.ok){const j=await response.json().catch(()=>({}));$('#bulkMessage').textContent=j.detail||'Export failed';return}const link=document.createElement('a');link.href=URL.createObjectURL(await response.blob());link.download='jo-ai-monitor-cases.zip';link.click();URL.revokeObjectURL(link.href)};form.appendChild(button)}
const caseEnhancer=new MutationObserver(()=>{enhanceCaseDetail();enhanceCaseQueue();enhanceBulkExport();schedulePolicySettings()});caseEnhancer.observe(sectionPage,{childList:true,subtree:true});
function activateRoute(){const allowed=new Set(identity.pages||[]),route=(location.hash||'').slice(1),page=allowed.has(route)?route:Object.values(navRoutes).find(x=>allowed.has(x));if(!page)return;const id=Object.keys(navRoutes).find(x=>navRoutes[x]===page);if(id==='evidenceNav')showEvidence();else $('#'+id).click()}
window.addEventListener('popstate',activateRoute);
window.addEventListener('hashchange',activateRoute);
(async()=>{configureTheme();await configureAuth();try{const me=await api('/api/auth/me');configureAccess(me);showApp();if((me.pages||[]).includes('evidence'))await load();activateRoute()}catch{showLogin()}})();
